export const materialById = new Map(MATERIALS.map((material) => [material.id, material]));

export type MaterialCost = Partial<Record<MaterialId, number>>;
export type MaterialTally = Record<MaterialId, number>;

const emptyTally = (): MaterialTally => ({
  cardboard: 0,
  petBottle: 0,
  glassBottle: 0,
  metalCan: 0,
  woodOffcut: 0,
  garment: 0,
});

/**
 * How many of each item the resident has recycled, derived from the kg already
 * tracked in monthlyImpact.wasteSources.
 */
export function earnedMaterials(): MaterialTally {
  const kgBySource = new Map(
    monthlyImpact.wasteSources.map((source) => [source.id, source.weightKg]),
  );
  const tally = emptyTally();
  for (const material of MATERIALS) {
    const kg = kgBySource.get(material.sourceId) ?? 0;
    tally[material.id] = Math.floor(kg / material.unitKg);
  }
  return tally;
}

export function spentMaterials(ownedIds: Iterable<string>): MaterialTally {
  const tally = emptyTally();
  for (const id of ownedIds) {
    const item = decorById.get(id);
    if (!item) continue;
    for (const [material, amount] of Object.entries(item.cost) as [
      MaterialId,
      number,
    ][]) {
      tally[material] += amount;
    }
  }
  return tally;
}

export function availableMaterials(ownedIds: Iterable<string>): MaterialTally {
  const earned = earnedMaterials();
  const spent = spentMaterials(ownedIds);
  const tally = emptyTally();
  for (const material of MATERIALS) {
    tally[material.id] = earned[material.id] - spent[material.id];
  }
  return tally;
}

export function canAfford(cost: MaterialCost, available: MaterialTally): boolean {
  return (Object.entries(cost) as [MaterialId, number][]).every(
    ([material, amount]) => available[material] >= amount,
  );
}

export const isFree = (cost: MaterialCost) => Object.keys(cost).length === 0;

